query ReviewThreadsPage(
  $owner: String!
  $name: String!
  $number: Int!
  $threadCursor: String
) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      reviewThreads(first: 100, after: $threadCursor) {
        pageInfo {
          hasNextPage
          endCursor
        }
        nodes {
          id
          isResolved
          isOutdated
          path
          line
          comments(first: 100) {
            nodes {
              databaseId
              author {
                login
              }
              body
              createdAt
              url
            }
          }
        }
      }
    }
  }
}
